.ltn__no-gutter > [class*='col-'] {
    /* No padding only for child columns */
    padding-right: 0;
    padding-left: 0;
}

.ltn__no-gutter-all [class*='col-'] {
    /* No padding for every columns */
    padding-right: 0;
    padding-left: 0;
}

@media (min-width: 992px) {

    /* Modify this based on column def */
    .ltn__custom-gutter {
        margin-left: -0px;
        margin-right: -0px;
    }

    .ltn__custom-gutter > [class*='col-'] {
        padding-right: 0px;
        padding-left: 0px;
    }

    .ltn__custom-gutter-all .row {
        margin-left: -15px;
        margin-right: -15px;
    }

    .ltn__custom-gutter-all .row [class*='col-'] {
        padding-right: 15px;
        padding-left: 15px;
    }
}

@media (max-width: 991px) {

    /* Modify this based on column def */
    .ltn__custom-gutter {
        margin-left: -15px;
        margin-right: -15px;
    }

    .ltn__custom-gutter > [class*='col-'] {
        padding-right: 15px;
        padding-left: 15px;
    }

    .ltn__custom-gutter-all {
        margin-left: -15px;
        margin-right: -15px;
    }

    .ltn__custom-gutter-all [class*='col-'] {
        padding-right: 15px;
        padding-left: 15px;
    }
}

@media (max-width: 767px) {

    /* Modify this based on column def */
    .ltn__product-gutter .row {
        margin-left: -8px;
        margin-right: -8px;
    }

    .ltn__product-gutter [class*='col-'] {
        padding-right: 8px;
        padding-left: 8px;
    }
}


/* ----------------------------------------------------
