#mkLightboxContainer {
    position: fixed;
    left: 0;
    top: 0;
    min-height: 100vh;
    min-width: 100vw;
    height: 100vh;
    width: 100vw;
    overflow: hidden;
    box-sizing: border-box;
    z-index: 999999;
    display: flex;
    align-items: center;
    justify-content: center;
}

#mkLightboxContainer > * {
    z-index: 99;
}

#overlay {
    position: absolute;
    left: 0;
    top: 0;
    height: 100vh;
    width: 100%;
    overflow: hidden;
    box-sizing: border-box;
    background: rgba(0,0,0,.85);
    z-index: 0;
}
.parent .popup-video {}
#mkLightboxContainer #mklbInner {
    position: relative;
    height: 100vh;
    transition: all .4s ease-in-out;
    margin-left: 0;
}

section.imageContainer {
    margin: 0;
    padding: 1em;
    box-sizing: border-box;
    border: none;
    height: 100vh;
    width: 100vw;
    display: flex;
    justify-content: center;
    align-items: center;
    float: left;
}

#mkLightboxContainer img,
#mkLightboxContainer video {
    background: #fff;
    box-shadow: 0 0 30px #222;
    max-height: 85vh;
    min-width: auto;
    max-width: 75vw;
    width: auto;
    height: auto;
}

#mkLightboxContainer #yt-video {
    width: 75vw;
    height: 42.1875vw; /* 75*9/16 */
}

.mklbItem:hover {
    cursor: pointer;
    font-style: italic;
}

#closeIconContainer {
    width: 25px;
    height: 25px;
    position: fixed;
    top: 15px;
    right: 15px;
    transition: transform .2s linear;
}

#closeIconContainer:hover {
    cursor: pointer;
    transform: rotate(90deg);
}

#closeIconContainer svg,
#prev svg,
#next svg,
#stopGallery svg, 
#playGallery svg{
    fill: white;
}

#prevContainer,
#nextContainer {
    position: fixed;
    left: 0;
    top: 0;
    height: 100vh;
    padding: 10px 5px 10px 5px;
    box-sizing: border-box;
    display: flex;
    justify-content: center;
    align-items: center;
    transition: all .2s ease-in;
}

#nextContainer {
    left: auto;
    right: 0;
}

#prevContainer:hover,
#nextContainer:hover {
    cursor: pointer;
    background: rgba(0,0,0,0.25);
}

#prev,
#next {
    width: 35px;
    height: 35px;
}

.grid {
    display: grid;
    align-content: flex-start;
    grid-gap: 1em;
}

.grid-3 {
    grid-template-columns: repeat(3, 1fr);
}

.grid-4 {
    grid-template-columns: repeat(4, 1fr);
}

.grid figure {
    width: 100%;
    margin: 0;
}

.grid img {
    width: 100%;
}

#controlContainer {
    position: absolute;
    top: 1em;
    left: .5em;
    display: flex;
}

#controlContainer > div {
    width: 2em;
}

#controlContainer > div:hover {
    cursor: pointer;
}

#controlContainer #stopGallery,
#controlContainer.stop #playGallery{
    opacity: 0.5;
}

#controlContainer.stop #stopGallery,
#controlContainer #playGallery{
    opacity: 1
}

@media screen and (max-width: 768px){
    .grid-2-sm {
        grid-template-columns: 1fr 1fr;
    }
}

@media screen and (max-width: 450px){
    .grid-12-xs {
        grid-template-columns: 1fr;
    }
}

.grid.grid-3.grid-2-sm.grid-12-xs {
  margin-bottom: 3em;
}

/****************************************************************************************************
top-bar.css
***********************************************************************************************/
.row2 {
    background-color: #132b61;
    border: none;
    padding: 4px 17px;
}

.ltn__header-top-area .auto-container {
    width: 94%;
    display: block;
    float: none;
    margin: auto;
}

.ltn__drop-menu > ul > li:hover > a {
    color: #fff;
}

.ltn__top-bar-menu > ul > li > i,
.ltn__top-bar-menu > ul > li > a > i {
    margin-right: 3px;
    color: var(--ltn__secondary-color);
}

.ltn__top-bar-menu .ltn__currency-menu .active-currency {
    font-size: 14px;
    font-weight: 700;
}

.ltn__top-bar-menu > ul {
    padding: 0;
    margin: 0;
}

.ltn__top-bar-menu > ul > li > i,
.ltn__top-bar-menu > ul > li > a > i {
    margin-right: 3px;
    color: #f9b702;
    font-size: 0.85em;
    font-weight: normal;
}

.ltn__top-bar-menu > ul > li {
    list-style: none;
    display: inline-block;
    margin: 0 15px 0 0;
    font-size: 14px;
    font-weight: 700;
}

.ltn__drop-menu ul li:hover > ul {
    top: 100%;
    opacity: 1;
    visibility: visible;
}

.ltn__currency-menu ul li ul {
    min-width: max-content !important;
}

.ltn__drop-menu ul li ul li a {
    color: inherit;
    font-weight: 500;
    font-size: 15px;
}

.ltn__drop-menu ul li ul {
    position: absolute;
    min-width: 150px;
    right: 0;
    background-color: #fff;
    z-index: 999;
    -webkit-box-shadow: var(--ltn__box-shadow-4);
    box-shadow: var(--ltn__box-shadow-4);
    border-top: 1px solid #ececec;
    top: 130%;
    padding: 7px 0;
    margin: 0;
    -webkit-transition: opacity .2s ease .1s, visibility .2s ease .1s, top .2s ease .1s;
    -o-transition: opacity .2s ease .1s, visibility .2s ease .1s, top .2s ease .1s;
    transition: opacity .2s ease .1s, visibility .2s ease .1s, top .2s ease .1s;
    opacity: 0;
    visibility: hidden;
}

.ltn__drop-menu {
    display: inline-block;
    text-align: left;
}

.ltn__drop-menu ul {
    margin-bottom: 0;
}

.ltn__drop-menu ul li ul li {
    display: block;
    padding: 0px 0.5em;
    font-size: 16px;
    color: var(--ltn__paragraph-color);
    font-weight: 500;
}

.ltn__top-bar-menu > ul > li:last-child {
    margin-right: 0;
}

img.flag {
    width: 18px;
    display: inline-block;
    padding-left: 2px;
}

.ltn__drop-menu ul li i {
    font-size: 0.7em;
    font-weight: 500;
    color: #ffc107;
}

.ltn__header-area {
    z-index: 9999;
    position: relative;
    color: #fff;
    background: #132b61;
}

.ltn__header-top-area {
    border-bottom: 1px solid;
    border-color: var(--border-color-3);
}

.ltn__header-top-area .ltn__social-media ul li {
    font-size: 14px;
    margin: 0 10px 0 0;
}

.top-area-color-white {
    background-color: #fff;
}

.top-area-color-white p,
.top-area-color-white a,
.top-area-color-white li,
.top-area-color-white .welcome p,
.top-area-color-white .welcome a,
.top-area-color-white .ltn__drop-menu > ul > li > a,
.top-area-color-white .ltn__drop-menu > ul > li:hover > a {
    color: var(--white);
}

.ltn__header-top-area .row {
    -webkit-box-align: center;
    -ms-flex-align: center;
    align-items: center;
}

.ltn__language-menu .dropdown-toggle::before {
    content: "\e939";
    font-size: 12px;
    position: absolute;
    top: 55%;
    right: -9px;
    -webkit-transform: translateY(-50%);
    -ms-transform: translateY(-50%);
    -moz-transform: translateY(-50%);
    -o-transform: translateY(-50%);
    transform: translateY(-50%);
    font-family: 'icomoon';
    color: #f9b702;
}

